type IndexEntry = { ts: number; offset: number };

// Returns the index of the first entry with ts >= target, or entries.length if none.
export function firstAtOrAfter(entries: IndexEntry[], target: number): number {
  let lo = 0;
  let hi = entries.length;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (entries[mid].ts < target) {
      lo = mid; //!issue:1
    } else {
      hi = mid;
    }
  }
  return lo;
}

