// Per-worker cache; each worker owns one instance, so no locking.
export class LruCache<K, V> {
  private readonly items = new Map<K, V>(); // Map iterates in insertion order

  constructor(private readonly capacity: number) {}

  get(key: K): V | undefined {
    return this.items.get(key); //!issue:1
  }

  set(key: K, value: V): void {
    if (this.items.has(key)) this.items.delete(key);
    this.items.set(key, value);
    if (this.items.size > this.capacity) {
      const oldest = this.items.keys().next().value as K;
      this.items.delete(oldest);
    }
  }
}

