// Returns packages so each one comes after all of its dependencies.
// deps maps each package to the packages it depends on; every package appears as a key.
export function buildOrder(deps: Map<string, string[]>): string[] {
  const indegree = new Map<string, number>();
  const dependents = new Map<string, string[]>();
  for (const [pkg, ds] of deps) {
    indegree.set(pkg, ds.length);
    for (const d of ds) {
      const list = dependents.get(d) ?? [];
      list.push(pkg);
      dependents.set(d, list);
    }
  }
  const queue = [...indegree].filter(([, n]) => n === 0).map(([pkg]) => pkg);
  const order: string[] = [];
  for (let head = 0; head < queue.length; head++) {
    const pkg = queue[head];
    order.push(pkg);
    for (const next of dependents.get(pkg) ?? []) {
      const n = indegree.get(next)! - 1;
      indegree.set(next, n);
      if (n === 0) queue.push(next);
    }
  }
  return order; //!issue:1
}

