// BuildOrder returns packages so each one comes after all of its dependencies.
// deps maps each package to the packages it depends on; every package appears as a key.
func BuildOrder(deps map[string][]string) []string {
	indegree := make(map[string]int, len(deps))
	dependents := make(map[string][]string)
	for pkg, ds := range deps {
		indegree[pkg] = len(ds)
		for _, d := range ds {
			dependents[d] = append(dependents[d], pkg)
		}
	}
	var queue []string
	for pkg, n := range indegree {
		if n == 0 {
			queue = append(queue, pkg)
		}
	}
	order := make([]string, 0, len(deps))
	for len(queue) > 0 {
		pkg := queue[0]
		queue = queue[1:]
		order = append(order, pkg)
		for _, next := range dependents[pkg] {
			indegree[next]--
			if indegree[next] == 0 {
				queue = append(queue, next)
			}
		}
	}
	return order //!issue:1
}

