use std::collections::{HashMap, VecDeque};

/// Returns packages so each one comes after all of its dependencies.
/// `deps` maps each package to the packages it depends on; every package appears as a key.
pub fn build_order(deps: &HashMap<String, Vec<String>>) -> Vec<String> {
    let mut indegree: HashMap<&str, usize> = HashMap::new();
    let mut dependents: HashMap<&str, Vec<&str>> = HashMap::new();
    for (pkg, ds) in deps {
        indegree.insert(pkg.as_str(), ds.len());
        for d in ds {
            dependents.entry(d.as_str()).or_default().push(pkg.as_str());
        }
    }
    let mut queue: VecDeque<&str> = indegree
        .iter()
        .filter(|(_, n)| **n == 0)
        .map(|(p, _)| *p)
        .collect();
    let mut order = Vec::with_capacity(deps.len());
    while let Some(pkg) = queue.pop_front() {
        order.push(pkg.to_string());
        for &next in dependents.get(pkg).into_iter().flatten() {
            let n = indegree.get_mut(next).expect("every package is a key");
            *n -= 1;
            if *n == 0 {
                queue.push_back(next);
            }
        }
    }
    order //!issue:1
}

