// Returns packages so each one comes after all of its dependencies.
// deps maps each package to the packages it depends on; every package appears as a key.
public static List<string> BuildOrder(IReadOnlyDictionary<string, List<string>> deps)
{
    var indegree = new Dictionary<string, int>();
    var dependents = new Dictionary<string, List<string>>();
    foreach (var (pkg, ds) in deps)
    {
        indegree[pkg] = ds.Count;
        foreach (var d in ds)
        {
            if (!dependents.TryGetValue(d, out var list)) dependents[d] = list = new List<string>();
            list.Add(pkg);
        }
    }
    var queue = new Queue<string>(indegree.Where(kv => kv.Value == 0).Select(kv => kv.Key));
    var order = new List<string>(deps.Count);
    while (queue.Count > 0)
    {
        var pkg = queue.Dequeue();
        order.Add(pkg);
        if (!dependents.TryGetValue(pkg, out var nexts)) continue;
        foreach (var next in nexts)
        {
            if (--indegree[next] == 0) queue.Enqueue(next);
        }
    }
    return order; //!issue:1
}

