// Returns packages so each one comes after all of its dependencies.
// deps maps each package to the packages it depends on; every package appears as a key.
public static List<String> buildOrder(Map<String, List<String>> deps) {
    Map<String, Integer> indegree = new HashMap<>();
    Map<String, List<String>> dependents = new HashMap<>();
    for (var e : deps.entrySet()) {
        indegree.put(e.getKey(), e.getValue().size());
        for (String d : e.getValue()) {
            dependents.computeIfAbsent(d, k -> new ArrayList<>()).add(e.getKey());
        }
    }
    Deque<String> queue = new ArrayDeque<>();
    indegree.forEach((pkg, n) -> { if (n == 0) queue.add(pkg); });
    List<String> order = new ArrayList<>(deps.size());
    while (!queue.isEmpty()) {
        String pkg = queue.poll();
        order.add(pkg);
        for (String next : dependents.getOrDefault(pkg, List.of())) {
            if (indegree.merge(next, -1, Integer::sum) == 0) queue.add(next);
        }
    }
    return order; //!issue:1
}

