// Merges overlapping or touching windows, e.g. [1,3] and [3,5] become [1,5].
export function mergeWindows(windows: Window[]): Window[] {
  const merged: Window[] = [];
  for (const w of windows) { //!issue:1
    const last = merged[merged.length - 1];
    if (last && w.start < last.end) { //!issue:2
      last.end = Math.max(last.end, w.end);
    } else {
      merged.push({ ...w });
    }
  }
  return merged;
}

